const items = $input.all();
const rows = items.map(item => {
  const props = item.json.properties || {};
  const row = {};
  for (const [key, value] of Object.entries(props)) {
    if (value.type === 'title') {
      row[key] = value.title?.map(t => t.plain_text).join('') || '';
    } else if (value.type === 'rich_text') {
      row[key] = value.rich_text?.map(t => t.plain_text).join('') || '';
    } else if (value.type === 'number') {
      row[key] = value.number || 0;
    } else if (value.type === 'select') {
      row[key] = value.select?.name || '';
    } else if (value.type === 'multi_select') {
      row[key] = value.multi_select?.map(s => s.name).join(', ') || '';
    } else if (value.type === 'date') {
      row[key] = value.date?.start || '';
    } else if (value.type === 'checkbox') {
      row[key] = value.checkbox ? 'Yes' : 'No';
    } else if (value.type === 'url') {
      row[key] = value.url || '';
    } else if (value.type === 'email') {
      row[key] = value.email || '';
    } else {
      row[key] = JSON.stringify(value[value.type] || '');
    }
  }
  row['Notion ID'] = item.json.id;
  row['Last Edited'] = item.json.last_edited_time;
  return { json: row };
});
return rows;

